(function()
 local v, th, eps = {value}, {threshold}, {epsilon}
 local mode, outm = '{mode}', '{output_mode}'
 local ok = false
 if mode == 'above' then ok = (v >= th)
 elseif mode == 'below' then ok = (v <= th)
 else ok = (math.abs(v - th) <= eps)
 end
 if outm == 'gate' then return ok and v or 0 end
 if outm == 'invert_binary' then return ok and 0 or 1 end
 return ok and 1 or 0
end)()

(function()
 local v, z = {value}, {zone}
 if z < 0 then z = 0 end
 local a = math.abs(v)
 if a <= z then return 0 end
 if not {soft} then return v end
 local sign = (v >= 0) and 1 or -1
 return sign * (a - z)
end)()

(function()
 local k = {slot}
 local v, a = {value}, {alpha}
 if a < 0.01 then a = 0.01 elseif a > 1 then a = 1 end
 local s = _cs_plugin_smooth
 if s[k] == nil then s[k] = v end
 s[k] = s[k] + (v - s[k]) * a
 return s[k]
end)()

(function()
 local k = {slot}
 local v, dec = {value}, {decay}
 if dec < 0 then dec = 0 end
 local s = _cs_plugin_peak
 if s[k] == nil then s[k] = v end
 if v > s[k] then s[k] = v else s[k] = s[k] - dec end
 if s[k] < v then s[k] = v end
 return s[k]
end)()

(function()
 local d = {divisor}
 if d == 0 then return 0 end
 return ({value}) % d
end)()

(function()
 local k = {slot}
 local v, dec = {value}, {decay}
 if dec < 0 then dec = 0 end
 local s = _cs_plugin_holdmin
 if s[k] == nil then s[k] = v end
 if v < s[k] then s[k] = v else s[k] = s[k] + dec end
 if s[k] > v then s[k] = v end
 return s[k]
end)()

(function()
 local v = {value}
 local n = tonumber(v)
 if n == nil then return {fallback} end
 return n
end)()

(function()
 local v = {value}
 if type(v) == 'number' then
 local d = math.floor({decimals} + 0.5)
 if d < 0 then d = 0 end
 return string.format('%.' .. d .. 'f', v)
 end
 return tostring(v)
end)()

(function()
 local v = {value}
 local s = tostring(v)
 if {lowercase} then s = s:lower() end
 return s
end)()
